css:
.cof-terms{display:grid; gap:8px}
.cof-row{display:flex; flex-wrap:wrap; align-items:center; gap:6px 10px; font-family:var(--mono); font-size:14.5px; padding:6px 10px; border:1px solid var(--rule); border-radius:8px; background:var(--panel)}
.cof-row.skip{color:var(--muted); border-style:dashed}
.cof-row.total{border-color:var(--c3); font-size:16px}
.cof-sign{font-weight:600; color:var(--c1); min-width:1em}
.cof-note{font-family:var(--body); font-size:13px}
.mat.detbar::before,.mat.detbar::after{border-top:none; border-bottom:none; width:3px}
.cof-cost summary{cursor:pointer; font-family:var(--display); font-size:14px; color:var(--muted)}
.cr-grid{display:grid; grid-template-columns:repeat(auto-fill,minmax(min(100%,260px),1fr)); gap:14px}
.cr-item{display:grid; gap:8px; justify-items:start; border:1px solid var(--rule); border-radius:8px; padding:10px; min-width:0}
.cr-eq{font-family:var(--mono); font-size:14px}
.code-in{font-family:var(--mono); font-size:16px; padding:8px 10px; border:1px solid var(--rule); border-radius:8px; background:var(--panel); color:var(--ink); width:100%}
.code-box{border:1px solid var(--rule); border-radius:8px; padding:10px 12px; display:grid; gap:6px}
.code-box .k{font-family:var(--mono); font-size:11.5px; letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
.code-nums{display:flex; flex-wrap:wrap; gap:4px; font-family:var(--mono); font-size:14px}
.code-nums span{padding:2px 6px; border-radius:4px; background:var(--paper)}
.code-nums span.sent{background:color-mix(in oklab,var(--c2) 14%,var(--panel))}
.code-nums .muted{background:none; color:var(--muted); font-family:var(--body)}
.code-text{flex-basis:100%; font-family:var(--display); font-size:20px; font-weight:700; color:var(--c3); margin-top:4px}
